function(container, apiUrl, tables) {
  const POLLING_INTERVAL = 5000; // 5秒ごとにポーリング
  let pollingTimer = null;
  let notificationPaused = false;

  // ===== ユーティリティ関数 =====
  function formatTime(seconds) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    if (h > 0) return `${h}h ${m}m`;
    if (m > 0) return `${m}m ${s}s`;
    return `${s}s`;
  }

  function formatDateTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleString('ja-JP', { 
      month: '2-digit', 
      day: '2-digit', 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  }

  function getAlertSeverityColor(severity) {
    switch(severity) {
      case 'CRITICAL': return '#c53030';
      case 'WARNING': return '#d69e2e';
      case 'INFO': return '#6b6b6b';
      default: return 'var(--text-muted)';
    }
  }

  function getAlertSeverityLabel(severity) {
    switch(severity) {
      case 'CRITICAL': return '緊急';
      case 'WARNING': return '警告';
      case 'INFO': return '情報';
      default: return severity;
    }
  }

  // ===== データ取得と画面更新 =====
  async function refreshDashboard() {
    try {
      // バックアップ実行履歴を取得（サマリー用）
      const histories = await window.aivicApi.list(1); // テーブルインデックス1: バックアップ実行履歴
      const runningJobs = await window.aivicApi.list(0); // テーブルインデックス0: バックアップジョブ
      const alerts = await window.aivicApi.list(14); // テーブルインデックス14: アラート発火履歴
      const notifications = await window.aivicApi.list(12); // テーブルインデックス12: 通知送信履歴

      // サマリー更新
      updateSummary(histories, runningJobs);

      // 実行中ジョブ一覧更新
      updateRunningJobs(runningJobs);

      // アラート表示更新
      updateAlerts(alerts);

      // 通知メッセージ更新
      if (!notificationPaused) {
        updateNotifications(notifications);
      }
    } catch (error) {
      console.error('Dashboard refresh error:', error);
    }
  }

  function updateSummary(histories, runningJobs) {
    if (!histories || !Array.isArray(histories)) {
      histories = [];
    }
    if (!runningJobs || !Array.isArray(runningJobs)) {
      runningJobs = [];
    }

    // 本日のデータをフィルタ
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const todayHistories = histories.filter(h => {
      const execDate = new Date(h.実行開始日時);
      execDate.setHours(0, 0, 0, 0);
      return execDate.getTime() === today.getTime();
    });

    const successCount = todayHistories.filter(h => h.実行ステータス === '成功').length;
    const failureCount = todayHistories.filter(h => h.実行ステータス === '失敗').length;
    const runningCount = runningJobs.filter(j => j.ステータス === '実行中').length;

    container.querySelector('[data-testid="kpi-success-count"]').textContent = successCount;
    container.querySelector('[data-testid="kpi-failure-count"]').textContent = failureCount;
    container.querySelector('[data-testid="kpi-running-count"]').textContent = runningCount;
  }

  function updateRunningJobs(runningJobs) {
    if (!runningJobs || !Array.isArray(runningJobs)) {
      runningJobs = [];
    }

    const running = runningJobs.filter(j => j.ステータス === '実行中');
    const tbody = container.querySelector('#running-jobs-tbody');
    const countSpan = container.querySelector('[data-testid="running-jobs-count"]');

    countSpan.textContent = `${running.length}件`;

    if (running.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 24px; text-align: center; color: var(--text-muted); font-size: 12px;">実行中のジョブはありません</td></tr>';
      return;
    }

    tbody.innerHTML = running.map((job, idx) => {
      const progress = job.進捗率 || 0;
      const elapsedSeconds = job.経過時間秒 || 0;
      const elapsedTime = formatTime(elapsedSeconds);

      return `
        <tr style="border-bottom: 1px solid var(--border);" data-id="${job.ジョブID}">
          <td style="padding: 8px; color: var(--text);">${job.ジョブ名 || '-'}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${job.バックアップ対象 || '-'}</td>
          <td style="padding: 8px; text-align: center;">
            <div style="width: 100%; height: 20px; background: var(--bg-main); border-radius: 2px; overflow: hidden; position: relative;">
              <div style="width: ${progress}%; height: 100%; background: var(--primary); transition: width 0.3s;"></div>
              <span style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 10px; color: var(--text); font-weight: 600;">${progress}%</span>
            </div>
          </td>
          <td style="padding: 8px; text-align: right; color: var(--text-muted); font-size: 12px;">${elapsedTime}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="job-detail-btn" data-id="${job.ジョブID}" style="background: transparent; border: 1px solid var(--border); color: var(--primary); padding: 4px 8px; border-radius: 2px; font-size: 11px; cursor: pointer; font-family: var(--font-family);">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    // 詳細ボタンのイベントリスナー
    tbody.querySelectorAll('.job-detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const jobId = e.target.dataset.id;
        showJobDetail(jobId, runningJobs);
      });
    });
  }

  function updateAlerts(alerts) {
    if (!alerts || !Array.isArray(alerts)) {
      alerts = [];
    }

    const container_el = container.querySelector('#alerts-container');
    const countSpan = container.querySelector('[data-testid="alert-count"]');

    // 未対応のアラートをフィルタ
    const activeAlerts = alerts.filter(a => a.アラート状態 !== '解決' && a.アラート状態 !== '無視').slice(0, 10);

    countSpan.textContent = `${activeAlerts.length}件`;

    if (activeAlerts.length === 0) {
      container_el.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">アラートはありません</div>';
      return;
    }

    container_el.innerHTML = activeAlerts.map(alert => {
      const severity = alert.アラートレベル || 'INFO';
      const severityColor = getAlertSeverityColor(severity);
      const severityLabel = getAlertSeverityLabel(severity);
      const firedAt = formatDateTime(alert.発火日時);

      return `
        <div style="padding: 12px; margin-bottom: 8px; background: var(--bg-main); border-left: 3px solid ${severityColor}; border-radius: 2px; cursor: pointer; transition: background 0.2s;" class="alert-item" data-id="${alert.アラート発火履歴ID}">
          <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px;">
            <span style="font-size: 11px; font-weight: 600; color: ${severityColor};">${severityLabel}</span>
            <span style="font-size: 10px; color: var(--text-muted);">${firedAt}</span>
          </div>
          <div style="font-size: 12px; color: var(--text); margin-bottom: 4px; line-height: 1.4;">${alert.アラートメッセージ || '-'}</div>
          <div style="font-size: 10px; color: var(--text-muted);">対象: ${alert.対象リソースタイプ || '-'}</div>
        </div>
      `;
    }).join('');

    // アラートアイテムのクリックイベント
    container_el.querySelectorAll('.alert-item').forEach(item => {
      item.addEventListener('click', (e) => {
        const alertId = e.currentTarget.dataset.id;
        // アラート詳細表示（簡易版）
        console.log('Alert clicked:', alertId);
      });
    });
  }

  function updateNotifications(notifications) {
    if (!notifications || !Array.isArray(notifications)) {
      notifications = [];
    }

    const container_el = container.querySelector('#notifications-container');

    // 送信成功した最新3件を表示
    const recentNotifications = notifications
      .filter(n => n.送信ステータス === '成功')
      .sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時))
      .slice(0, 3);

    if (recentNotifications.length === 0) {
      container_el.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">通知はありません</div>';
      return;
    }

    container_el.innerHTML = recentNotifications.map(notif => {
      const sentAt = formatDateTime(notif.送信日時);
      const channel = notif.送信チャネル || '-';

      return `
        <div style="padding: 12px; margin-bottom: 8px; background: var(--bg-main); border-radius: 2px; border: 1px solid var(--border);">
          <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px;">
            <span style="font-size: 11px; font-weight: 600; color: var(--primary);">${channel}</span>
            <span style="font-size: 10px; color: var(--text-muted);">${sentAt}</span>
          </div>
          <div style="font-size: 12px; color: var(--text); line-height: 1.4; word-break: break-word;">${notif.通知内容 || '-'}</div>
        </div>
      `;
    }).join('');
  }

  function showJobDetail(jobId, runningJobs) {
    const job = runningJobs.find(j => j.ジョブID === jobId);
    if (!job) return;

    const modal = container.querySelector('#job-detail-modal');
    const content = container.querySelector('#job-detail-content');

    const nextExecTime = formatDateTime(job.次回予定実行日時);
    const lastExecTime = formatDateTime(job.最終実行日時);
    const lastResult = job.最終実行結果 || '-';

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 120px 1fr; gap: 12px; row-gap: 8px;">
        <div style="color: var(--text-muted); font-weight: 500;">ジョブID</div>
        <div style="color: var(--text);">${job.ジョブID || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">ジョブ名</div>
        <div style="color: var(--text);">${job.ジョブ名 || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">バックアップ対象</div>
        <div style="color: var(--text);">${job.バックアップ対象 || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">バックアップタイプ</div>
        <div style="color: var(--text);">${job.バックアップタイプ || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">スケジュール</div>
        <div style="color: var(--text);">${job.スケジュール種別 || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">ステータス</div>
        <div style="color: var(--text);">${job.ステータス || '-'}</div>

        <div style="color: var(--text-muted); font-weight: 500;">最終実行</div>
        <div style="color: var(--text);">${lastExecTime}</div>

        <div style="color: var(--text-muted); font-weight: 500;">最終結果</div>
        <div style="color: var(--text);">${lastResult}</div>

        <div style="color: var(--text-muted); font-weight: 500;">次回予定</div>
        <div style="color: var(--text);">${nextExecTime}</div>

        <div style="color: var(--text-muted); font-weight: 500;">保持期間</div>
        <div style="color: var(--text);">${job.保持期間日数 || '-'}日</div>

        <div style="color: var(--text-muted); font-weight: 500;">通知先</div>
        <div style="color: var(--text);">${job.通知先メールアドレス || '-'}</div>
      </div>
    `;

    modal.style.display = 'flex';
  }

  // ===== イベントリスナー登録 =====
  const refreshBtn = container.querySelector('[data-testid="refresh-button"]');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', refreshDashboard);
  }

  const notificationSettingsBtn = container.querySelector('[data-testid="notification-settings-button"]');
  if (notificationSettingsBtn) {
    notificationSettingsBtn.addEventListener('click', () => {
      // 通知設定画面への遷移（シェルのナビゲーション機能を使用）
      window.location.href = '/panels/notification-settings.html';
    });
  }

  const pauseToggle = container.querySelector('#notification-pause-toggle');
  if (pauseToggle) {
    pauseToggle.addEventListener('change', (e) => {
      notificationPaused = e.target.checked;
    });
  }

  const jobDetailCloseBtn = container.querySelector('#job-detail-close');
  const jobDetailCloseBtnBottom = container.querySelector('#job-detail-close-btn');
  const jobDetailModal = container.querySelector('#job-detail-modal');

  if (jobDetailCloseBtn) {
    jobDetailCloseBtn.addEventListener('click', () => {
      jobDetailModal.style.display = 'none';
    });
  }

  if (jobDetailCloseBtnBottom) {
    jobDetailCloseBtnBottom.addEventListener('click', () => {
      jobDetailModal.style.display = 'none';
    });
  }

  // モーダル背景クリックで閉じる
  if (jobDetailModal) {
    jobDetailModal.addEventListener('click', (e) => {
      if (e.target === jobDetailModal) {
        jobDetailModal.style.display = 'none';
      }
    });
  }

  // Escキーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const modal = container.querySelector('#job-detail-modal');
      if (modal && modal.style.display !== 'none') {
        modal.style.display = 'none';
      }
    }
  });

  // ===== 初期化と定期更新 =====
  refreshDashboard();
  pollingTimer = setInterval(refreshDashboard, POLLING_INTERVAL);

  // クリーンアップ
  return () => {
    if (pollingTimer) {
      clearInterval(pollingTimer);
    }
  };
}
